package com.pocketmusic.android;
import android.content.*;
import androidx.test.platform.app.InstrumentationRegistry;
import org.junit.*;
import java.io.*;
import java.nio.file.Files;
import java.util.*;
import static org.junit.Assert.*;
public class DiscoveryMetadataTest {
 private Context context;private File root;private String prefs;
 @Before public void setup()throws Exception{Context app=InstrumentationRegistry.getInstrumentation().getTargetContext();root=Files.createTempDirectory(app.getCacheDir().toPath(),"discovery-test-").toFile();prefs="discovery-test-"+UUID.randomUUID();context=new ContextWrapper(app){@Override public File getNoBackupFilesDir(){return root;}@Override public File getCacheDir(){return root;}@Override public SharedPreferences getSharedPreferences(String name,int mode){return super.getSharedPreferences(prefs,mode);}};}
 @After public void cleanup(){context.getSharedPreferences("music",0).edit().clear().commit();File[] files=root.listFiles();if(files!=null)for(File f:files)f.delete();root.delete();context.deleteSharedPreferences(prefs);}
 private Track song(String id){return new Track(id,"Quiet song","Artist",191,true,"");}
 private void cache(String scope)throws Exception{Recommendations.save(context,scope,MusicTaste.version(context),List.of(new DiscoveryShelf("Your daily mix","Original test seed",List.of(song("abcdefghijk")))),0);}
 @Test public void metadataRoundTripRetainsMusicProvenanceAndArtwork()throws Exception{Track song=new Track("abcdefghijk","Music","Artist",191,true,"https://i.ytimg.com/vi/abcdefghijk/hqdefault.jpg");List<Track> tracks=TrackMetadata.parse(TrackMetadata.encode(List.of(song,song)),12);assertEquals(1,tracks.size());assertEquals("Artist · 3:11",tracks.get(0).subtitle());assertTrue(tracks.get(0).music);assertEquals(song.artworkUrl,tracks.get(0).artworkUrl);}
 @Test public void accountCacheNeverLeaksAcrossReconnectOrDisconnect()throws Exception{YouTubeSession.save(context,"SAPISID=synthetic-one");String first=Recommendations.scope(context);cache(first);assertEquals(1,Recommendations.cached(context).size());YouTubeSession.save(context,"SAPISID=synthetic-two");assertNotEquals(first,Recommendations.scope(context));assertTrue(Recommendations.cached(context).isEmpty());cache(Recommendations.scope(context));YouTubeSession.disconnect(context);assertTrue(Recommendations.cached(context).isEmpty());}
 @Test public void changedTasteInvalidatesFreshnessWithoutRelabelingCachedSource()throws Exception{cache("guest");assertTrue(Recommendations.fresh(context));MusicTaste.choose(context,"New artist",List.of("Jazz"));assertFalse(Recommendations.fresh(context));assertEquals("Original test seed",Recommendations.shelves(context).get(0).reason);assertEquals(1,Recommendations.cached(context).size());}
 @Test public void futureCachesAreNotFresh()throws Exception{cache("guest");context.getSharedPreferences("music",0).edit().putLong("musicTime",System.currentTimeMillis()+86400000L).commit();assertFalse(Recommendations.fresh(context));}
 @Test public void legacyGeneralVideoCacheIsNeverShown()throws Exception{context.getSharedPreferences("music",0).edit().putString("feedScope","guest").putString("feedTracks",TrackMetadata.encode(List.of(new Track("abcdefghijk","Music news podcast","Channel",200)))).putLong("feedTime",System.currentTimeMillis()).commit();assertTrue(Recommendations.cached(context).isEmpty());}
 @Test public void catalogueFailureKeepsCachedSongsWithoutGeneralVideoFallback()throws Exception{cache("guest");try{Recommendations.fetch(context,"test-failure",(q,p)->{throw new IOException("Offline");});fail();}catch(IOException expected){}assertEquals("abcdefghijk",Recommendations.cached(context).get(0).id);}
 @Test public void partialSourcesOnlyStoreVerifiedMusic()throws Exception{Recommendations.fetch(context,"test-partial",(q,p)->{if(p.endsWith("-0"))throw new IOException("Offline");return List.of(song("abcdefghijk"),new Track("12345678901","music gameplay","Creator",200));});assertFalse(Recommendations.cached(context).isEmpty());for(Track t:Recommendations.cached(context))assertTrue(t.music);assertEquals(1,context.getSharedPreferences("music",0).getInt("musicPartialFailures",0));}
 @Test public void profileChangeDiscardsInFlightRefresh()throws Exception{cache("guest");Recommendations.fetch(context,"test-change",(q,p)->{MusicTaste.choose(context,"Different artist",List.of("Rock"));return List.of(song("12345678901"));});assertEquals("abcdefghijk",Recommendations.cached(context).get(0).id);assertFalse(Recommendations.fresh(context));}
 @Test public void likingHidingAndUndoChangeTheVisibleCollection()throws Exception{Track t=song("abcdefghijk");assertTrue(MusicTaste.toggleLike(context,t));assertEquals(1,MusicTaste.liked(context).size());cache("guest");MusicTaste.hide(context,t.id,true);assertTrue(Recommendations.cached(context).isEmpty());MusicTaste.hide(context,t.id,false);assertEquals(1,Recommendations.cached(context).size());assertEquals(1,MusicTaste.liked(context).size());assertFalse(MusicTaste.toggleLike(context,t));assertTrue(MusicTaste.liked(context).isEmpty());}
 @Test public void likedMetadataSurvivesKnownSongEviction(){Track favorite=song("abcdefghijk");MusicTaste.toggleLike(context,favorite);List<Track> many=new ArrayList<>();for(int i=0;i<220;i++)many.add(new Track(String.format(Locale.ROOT,"%011d",i),"Song "+i,"Artist "+i,180,true,""));MusicTaste.remember(context,many);assertEquals(200,MusicTaste.known(context).size());assertEquals(favorite.id,MusicTaste.liked(context).get(0).id);}
}
